package com.fooddelivery.order.dto;import java.util.*;public class OrderRequest{private Long userId;private String restaurantId;private List<OrderItem> items;private double totalAmount;public Long getUserId(){return userId;}public void setUserId(Long v){userId=v;}public String getRestaurantId(){return restaurantId;}public void setRestaurantId(String v){restaurantId=v;}public List<OrderItem> getItems(){return items;}public void setItems(List<OrderItem> v){items=v;}public double getTotalAmount(){return totalAmount;}public void setTotalAmount(double v){totalAmount=v;}public static class OrderItem{private String itemId,name;private int quantity;private double price;public String getItemId(){return itemId;}public void setItemId(String v){itemId=v;}public String getName(){return name;}public void setName(String v){name=v;}public int getQuantity(){return quantity;}public void setQuantity(int v){quantity=v;}public double getPrice(){return price;}public void setPrice(double v){price=v;}}}
